'use client';

import { useEffect, useId, useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { SECTION, TOOLS, toolOf, type ToolId } from './data';
import { DriftRows } from './drift-rows';
import { Glass } from './glass';
import {
  CONNECT_MS,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  type ToolsState,
} from './session';
import { ToolPills } from './tool-pills';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

function spokenLineOf(state: ToolsState) {
  if (state.openId === null) {
    return '';
  }
  const tool = toolOf(state.openId);
  if (!tool) {
    return '';
  }
  if (state.isConnecting) {
    return `Connecting ${tool.name}`;
  }
  if (state.connected.includes(tool.id)) {
    return `${tool.name} is connected`;
  }
  return `${tool.name}: ${tool.summary}`;
}

function isConnectedTool(openId: ToolId | null, connected: ToolId[]) {
  if (openId === null) {
    return false;
  }
  return connected.includes(openId);
}

function openToolOf(openId: ToolId | null) {
  if (openId === null) {
    return null;
  }
  return toolOf(openId) ?? null;
}

export default function Integrations04() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const glassId = useId();
  const [isHovering, setIsHovering] = useState(false);
  const { openId, isConnecting, connected } = state;
  const openTool = openToolOf(openId);
  const isOpen = openId !== null;
  const isOffScreen = !isInView;
  const isHeld = isOffScreen || isHovering || isOpen;
  const isOpenConnected = isConnectedTool(openId, connected);
  const message = spokenUnless(isAutoplaying, spokenLineOf(state));
  const canReplay = isFinished && !isAutoplaying;

  useEffect(() => {
    if (!isConnecting) {
      return;
    }
    const timer = setTimeout(() => act({ type: 'connected' }), CONNECT_MS);
    return () => clearTimeout(timer);
  }, [isConnecting, act]);

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  function openByPerson(id: ToolId) {
    act({ type: 'opened', id });
    focusLater('[data-connect]');
  }

  function closeByPerson() {
    const closing = openId;
    act({ type: 'closed' });
    if (closing !== null) {
      focusLater(`[data-tool="${closing}"]`);
    }
  }

  function disconnectOpen() {
    if (openId !== null) {
      act({ type: 'disconnected', id: openId });
    }
  }

  function closeOnEscape(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'Escape' && isOpen) {
      event.preventDefault();
      closeByPerson();
    }
  }

  function holdWhileHovering(event: React.PointerEvent<HTMLDivElement>) {
    if (event.pointerType === 'mouse') {
      setIsHovering(true);
    }
  }

  function releaseHover() {
    setIsHovering(false);
  }

  return (
    <div ref={ref} onKeyDown={closeOnEscape} className='@container'>
      <section className='px-4 py-16 @2xl:px-6 @2xl:py-24 @5xl:px-8'>
        <div className='mx-auto flex max-w-4xl flex-col items-center gap-10'>
          <header className='flex max-w-xl flex-col items-center gap-3 text-center'>
            <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
              {SECTION.title}
            </h2>
            <p className='text-muted-foreground text-base text-pretty'>
              {SECTION.description}
            </p>
          </header>
          <div
            data-held={isHeld}
            onPointerEnter={holdWhileHovering}
            onPointerLeave={releaseHover}
            className='group/reel relative h-52 w-full'
          >
            <div
              aria-hidden='true'
              className='absolute inset-0 mask-x-from-85% motion-reduce:mask-none'
            >
              <DriftRows
                layer='grey'
                connected={connected}
                onPick={openByPerson}
              />
            </div>
            <div
              aria-hidden='true'
              data-open={isOpen}
              className='pointer-events-none absolute inset-0 transition-opacity delay-200 duration-200 [clip-path:inset(0_calc(50%_-_3rem)_round_3rem)] data-[open=true]:opacity-0 data-[open=true]:delay-0 data-[open=true]:duration-100'
            >
              <DriftRows layer='colour' connected={connected} />
            </div>
            <Glass
              layoutId={glassId}
              tool={openTool}
              isConnected={isOpenConnected}
              isConnecting={isConnecting}
              isConnectPressed={pressed === 'connect'}
              onConnect={() => act({ type: 'connectStarted' })}
              onDisconnect={disconnectOpen}
              onClose={closeByPerson}
            />
          </div>
          <div className='flex flex-col items-center gap-3'>
            <p className='text-muted-foreground flex items-baseline gap-1 text-xs tabular-nums'>
              <MotionNumber value={connected.length} />
              <span>of {TOOLS.length} connected</span>
            </p>
            <ToolPills
              connected={connected}
              openId={openId}
              pressed={pressed}
              onPick={openByPerson}
            />
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay'
            />
          </div>
        </div>
      </section>
      <LiveRegion message={message} />
    </div>
  );
}

'use client';

import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';

import { TOOLS, type Tool, type ToolId } from './data';

export type DriftLayer = 'grey' | 'colour';

type DriftStyle = React.CSSProperties & { '--marquee-duration': string };

type RowSpec = {
  id: string;
  seconds: number;
  isReversed: boolean;
  offset: number;
};

const ROWS: RowSpec[] = [
  { id: 'top', seconds: 46, isReversed: false, offset: 0 },
  { id: 'middle', seconds: 58, isReversed: true, offset: 4 },
  { id: 'bottom', seconds: 38, isReversed: false, offset: 8 },
];

/** Half of the copies is what one loop travels, so two copies must be wider than the stage. */
const COPIES = [0, 1, 2, 3];

const TRACK =
  'flex w-max motion-safe:animate-marquee group-data-[held=true]/reel:[animation-play-state:paused]!';

function rotatedTools(offset: number) {
  const tail = TOOLS.slice(0, offset);
  const head = TOOLS.slice(offset);
  return [...head, ...tail];
}

function directionOf(isReversed: boolean) {
  if (isReversed) {
    return '[animation-direction:reverse]!';
  }
  return undefined;
}

function quietOf(isConnected: boolean) {
  if (isConnected) {
    return undefined;
  }
  return 'opacity-70 grayscale';
}

type GreyTileProps = {
  tool: Tool;
  isConnected: boolean;
  onPick: (id: ToolId) => void;
};

function GreyTile({ tool, isConnected, onPick }: GreyTileProps) {
  return (
    <button
      type='button'
      tabIndex={-1}
      onClick={() => onPick(tool.id)}
      className={cn(
        'block cursor-pointer rounded-[10px] transition-[filter,opacity] duration-300 ease-(--ease-out-strong) outline-none hover:opacity-100',
        quietOf(isConnected)
      )}
    >
      <BrandTile brand={tool.id} size='2xl' />
    </button>
  );
}

type DriftRowProps = {
  row: RowSpec;
  layer: DriftLayer;
  connected: ToolId[];
  onPick?: (id: ToolId) => void;
};

function Tile({
  tool,
  layer,
  connected,
  onPick,
}: Omit<DriftRowProps, 'row'> & { tool: Tool }) {
  if (layer === 'grey' && onPick) {
    const isConnected = connected.includes(tool.id);
    return <GreyTile tool={tool} isConnected={isConnected} onPick={onPick} />;
  }
  return <BrandTile brand={tool.id} size='2xl' />;
}

function DriftRow({ row, layer, connected, onPick }: DriftRowProps) {
  const tools = rotatedTools(row.offset);
  const style: DriftStyle = { '--marquee-duration': `${row.seconds}s` };

  return (
    <div className='flex overflow-hidden'>
      <div style={style} className={cn(TRACK, directionOf(row.isReversed))}>
        {COPIES.map((copy) => (
          <ul key={copy} className='flex shrink-0 gap-3 pe-3'>
            {tools.map((tool) => (
              <li key={tool.id}>
                <Tile
                  tool={tool}
                  layer={layer}
                  connected={connected}
                  onPick={onPick}
                />
              </li>
            ))}
          </ul>
        ))}
      </div>
    </div>
  );
}

type DriftRowsProps = Omit<DriftRowProps, 'row'>;

/** The grey layer and the colour layer are the same rows on the same clock, so they stay in step. */
export function DriftRows({ layer, connected, onPick }: DriftRowsProps) {
  return (
    <div className='absolute inset-x-0 top-8 flex flex-col gap-3'>
      {ROWS.map((row) => (
        <DriftRow
          key={row.id}
          row={row}
          layer={layer}
          connected={connected}
          onPick={onPick}
        />
      ))}
    </div>
  );
}

'use client';

import { motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { XIcon } from '@/registry/ndeko/lib/icons';
import { springOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';

import type { Tool } from './data';

const WINDOW_STYLE = { borderRadius: 48 };

const PANEL_STYLE = { borderRadius: 18 };

const LABELS: Record<MorphState, string> = {
  idle: 'Connect',
  busy: 'Connecting',
  done: 'Connected',
};

const CONTENT_ARRIVAL = { duration: 0.18, delay: 0.12 };

function morphStateOf(isConnected: boolean, isConnecting: boolean): MorphState {
  if (isConnected) {
    return 'done';
  }
  if (isConnecting) {
    return 'busy';
  }
  return 'idle';
}

function contentStartOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return false;
  }
  return { opacity: 0 };
}

type FrameProps = {
  layoutId: string;
};

function WindowFrame({ layoutId }: FrameProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <motion.div
      layoutId={layoutId}
      style={WINDOW_STYLE}
      transition={springOf(shouldReduceMotion)}
      className='hairline-ring ring-foreground/15 h-full w-24 shadow-[0_10px_28px_-14px_rgb(0_0_0/0.28)]'
    />
  );
}

type PanelFrameProps = FrameProps & {
  tool: Tool;
  isConnected: boolean;
  isConnecting: boolean;
  isConnectPressed: boolean;
  onConnect: () => void;
  onDisconnect: () => void;
  onClose: () => void;
};

function PanelFrame({
  layoutId,
  tool,
  isConnected,
  isConnecting,
  isConnectPressed,
  onConnect,
  onDisconnect,
  onClose,
}: PanelFrameProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const morphState = morphStateOf(isConnected, isConnecting);

  return (
    <motion.div
      layoutId={layoutId}
      style={PANEL_STYLE}
      transition={springOf(shouldReduceMotion)}
      role='dialog'
      aria-label={`Connect ${tool.name}`}
      className='bg-card hairline-ring ring-foreground/15 dark:bg-popover pointer-events-auto h-full w-full max-w-sm shadow-[0_10px_28px_-14px_rgb(0_0_0/0.28)]'
    >
      <motion.div
        key={tool.id}
        initial={contentStartOf(shouldReduceMotion)}
        animate={{ opacity: 1 }}
        transition={CONTENT_ARRIVAL}
        className='flex h-full flex-col gap-3 p-4'
      >
        <div className='flex items-center gap-3'>
          <BrandTile brand={tool.id} size='2xl' />
          <div className='flex min-w-0 flex-1 flex-col'>
            <h3 className='truncate text-sm font-medium'>{tool.name}</h3>
            <p className='text-muted-foreground text-xs'>{tool.kind}</p>
          </div>
          <Button
            type='button'
            variant='ghost'
            size='icon-sm'
            aria-label={`Close ${tool.name}`}
            onClick={onClose}
            className='text-muted-foreground self-start'
          >
            <XIcon />
          </Button>
        </div>
        <p className='text-muted-foreground text-[13px] text-pretty'>
          {tool.summary}
        </p>
        <div className='mt-auto flex items-center gap-2'>
          <MorphButton
            type='button'
            data-connect=''
            state={morphState}
            labels={LABELS}
            onClick={onConnect}
            className={cn(pressedSolidOf(isConnectPressed))}
          />
          {isConnected && (
            <Button
              type='button'
              variant='ghost'
              size='sm'
              onClick={onDisconnect}
            >
              Disconnect
            </Button>
          )}
        </div>
      </motion.div>
    </motion.div>
  );
}

type GlassProps = {
  layoutId: string;
  tool: Tool | null;
  isConnected: boolean;
  isConnecting: boolean;
  isConnectPressed: boolean;
  onConnect: () => void;
  onDisconnect: () => void;
  onClose: () => void;
};

/** One frame that is the window while nothing is open and the panel once a tool is, so the window grows into it. */
export function Glass({ layoutId, tool, ...panel }: GlassProps) {
  let frame = <WindowFrame layoutId={layoutId} />;
  if (tool !== null) {
    frame = <PanelFrame layoutId={layoutId} tool={tool} {...panel} />;
  }

  return (
    <div className='pointer-events-none absolute inset-0 flex justify-center'>
      {frame}
    </div>
  );
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { CheckIcon } from '@/registry/ndeko/lib/icons';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';

import { TOOLS, type ToolId } from './data';

const CONNECTED_PILL = 'bg-success/10 text-success-foreground';

const WAITING_PILL =
  'bg-foreground/[0.05] text-foreground hover:bg-foreground/[0.08]';

function toneOf(isConnected: boolean) {
  if (isConnected) {
    return CONNECTED_PILL;
  }
  return WAITING_PILL;
}

type ToolPillsProps = {
  connected: ToolId[];
  openId: ToolId | null;
  pressed: string | null;
  onPick: (id: ToolId) => void;
};

export function ToolPills({
  connected,
  openId,
  pressed,
  onPick,
}: ToolPillsProps) {
  return (
    <ul
      aria-label='Tools to connect'
      className='flex max-w-3xl flex-wrap justify-center gap-1.5'
    >
      {TOOLS.map((tool) => {
        const isConnected = connected.includes(tool.id);
        const isOpen = openId === tool.id;
        const isPressed = pressed === `tool-${tool.id}`;

        return (
          <li key={tool.id}>
            <button
              type='button'
              data-tool={tool.id}
              aria-expanded={isOpen}
              onClick={() => onPick(tool.id)}
              className={cn(
                'flex h-7 cursor-pointer items-center gap-1.5 rounded-full ps-1.5 pe-2.5 text-xs transition-[color,background-color,scale] duration-150 ease-(--ease-out-strong) active:scale-[0.97]',
                toneOf(isConnected),
                pressedQuietOf(isPressed),
                FOCUS_RING
              )}
            >
              <BrandTile brand={tool.id} size='sm' />
              {tool.name}
              {isConnected && <CheckIcon className='size-3' />}
              {isConnected && <span className='sr-only'>, connected</span>}
            </button>
          </li>
        );
      })}
    </ul>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import type { ToolId } from './data';

export type ToolsState = {
  connected: ToolId[];
  openId: ToolId | null;
  isConnecting: boolean;
};

export type ToolsAction =
  | { type: 'opened'; id: ToolId }
  | { type: 'closed' }
  | { type: 'connectStarted' }
  | { type: 'connected' }
  | { type: 'disconnected'; id: ToolId };

type Step = SessionStep<ToolsState, ToolsAction>;

export const INITIAL: ToolsState = {
  connected: [],
  openId: null,
  isConnecting: false,
};

export const CONNECT_MS = 800;

function connectStarted(state: ToolsState): ToolsState {
  const { openId } = state;
  if (openId === null) {
    return state;
  }
  const isAlready = state.connected.includes(openId);
  if (isAlready) {
    return state;
  }
  return { ...state, isConnecting: true };
}

function connected(state: ToolsState): ToolsState {
  const { openId } = state;
  if (openId === null || !state.isConnecting) {
    return state;
  }
  const next = [...state.connected, openId];
  return { ...state, connected: next, isConnecting: false };
}

export function reducer(state: ToolsState, action: ToolsAction): ToolsState {
  switch (action.type) {
    case 'opened':
      return { ...state, openId: action.id, isConnecting: false };
    case 'closed':
      return { ...state, openId: null, isConnecting: false };
    case 'connectStarted':
      return connectStarted(state);
    case 'connected':
      return connected(state);
    case 'disconnected': {
      const rest = state.connected.filter((id) => id !== action.id);
      return { ...state, connected: rest };
    }
  }
}

const DEMO_TOOLS: ToolId[] = ['gmail', 'github', 'notion', 'stripe'];

function connecting(id: ToolId, firstAfter: number): Step[] {
  return [
    {
      after: firstAfter,
      by: 'demo',
      press: `tool-${id}`,
      action: { type: 'opened', id },
    },
    {
      after: 1500,
      by: 'demo',
      press: 'connect',
      action: { type: 'connectStarted' },
    },
    { after: 2600, by: 'demo', action: { type: 'closed' } },
  ];
}

/**
 * Four tools are opened and connected one after the other, so the rows fill in with colour as the
 * round goes on.
 */
export const SCRIPT: Step[] = DEMO_TOOLS.flatMap((id, index) => {
  const isFirst = index === 0;
  let firstAfter = 1400;
  if (isFirst) {
    firstAfter = 2200;
  }
  return connecting(id, firstAfter);
});

/** Under reduced motion three tools are connected and a fourth waits to be. */
export const RESTING: ToolsState = {
  connected: ['gmail', 'github', 'linear'],
  openId: 'notion',
  isConnecting: false,
};

export const LOOP_AFTER_MS = 2800;

import { BRANDS } from '@/registry/ndeko/lib/brand-logos';

export type ToolId =
  | 'gmail'
  | 'notion'
  | 'linear'
  | 'github'
  | 'figma'
  | 'stripe'
  | 'zoom'
  | 'googledrive'
  | 'jira'
  | 'sentry'
  | 'loom'
  | 'dropbox';

export type Tool = {
  id: ToolId;
  name: string;
  kind: string;
  summary: string;
};

export const SECTION = {
  title: 'Bring your stack in one tool at a time',
  description:
    'Press a tool to see what Harbourline does with it, then connect it. Connected tools keep their colour, so the rows fill in as your stack comes together.',
};

type ToolSeed = {
  id: ToolId;
  kind: string;
  summary: string;
};

const SEEDS: ToolSeed[] = [
  {
    id: 'gmail',
    kind: 'Mail',
    summary:
      'Threads from your inbox become tasks, with the sender and the files attached.',
  },
  {
    id: 'notion',
    kind: 'Docs',
    summary:
      'Pages you link show their title and status on the task they belong to.',
  },
  {
    id: 'linear',
    kind: 'Issues',
    summary: 'Issues stay in step with Harbourline tasks, in both directions.',
  },
  {
    id: 'github',
    kind: 'Code',
    summary:
      'Pull requests attach to the task and close it when they are merged.',
  },
  {
    id: 'figma',
    kind: 'Design',
    summary:
      'Frames appear on the task as a live preview, never as a stale export.',
  },
  {
    id: 'stripe',
    kind: 'Payments',
    summary: 'Paid invoices mark their task as billed, with no copy and paste.',
  },
  {
    id: 'zoom',
    kind: 'Calls',
    summary: 'Meetings you start from a task keep their notes on that task.',
  },
  {
    id: 'googledrive',
    kind: 'Files',
    summary: 'Files you pick open from the task and stay in your own Drive.',
  },
  {
    id: 'jira',
    kind: 'Issues',
    summary:
      'Tickets sync their status to the card, so nobody updates two boards.',
  },
  {
    id: 'sentry',
    kind: 'Errors',
    summary: 'A new error opens a task with its stack trace already in it.',
  },
  {
    id: 'loom',
    kind: 'Video',
    summary:
      'Recordings play on the task, next to the comment that asked for them.',
  },
  {
    id: 'dropbox',
    kind: 'Files',
    summary: 'Shared folders show their latest files on the task.',
  },
];

export const TOOLS: Tool[] = SEEDS.map((seed) => ({
  ...seed,
  name: BRANDS[seed.id].title,
}));

export function toolOf(id: ToolId) {
  return TOOLS.find((tool) => tool.id === id);
}
